        assertNothingChanged("RK-6", "C1");
    }

    @Test
    void activation_partitionMismatch422_fullRollback() throws Exception {
        setupLegWithBags();
        sealedContainer("C1", "SEAL-1", List.of("BAG01", "BAG02"));

